mapper.delete:
DELETE FROM emp01_person
 WHERE emp01_person_id  = #{personId}
   AND emp01_company_id = #{companyId}

mapper.select:
WITH paging_data AS ( SELECT emp01_person_id AS person_id, sys01_company_nm AS company_nm, emp01_kor_nm AS kor_nm, emp01_emp_no AS emp_no, f_get_empTrans(emp01_person_id, f_sysdate()::date, 'pos_nm') AS pos_nm, f_get_empTrans(emp01_person_id, f_sysdate()::date, 'org_code_nm') AS org_nm, emp01_office_telno AS office_telno, emp01_mobile_telno AS mobile_telno, emp01_email_addr AS email_addr, emp01_hire_date AS hire_date, emp01_note AS note, ROW_NUMBER() OVER (ORDER BY sys01_company_nm COLLATE "ko-KR-x-icu" ASC, emp01_kor_nm COLLATE "ko-KR-x-icu" ASC) AS row_num FROM emp01_person INNER JOIN emp03_trans ON emp03_person_id = emp01_person_id INNER JOIN sys01_company ON sys01_company_id = emp01_company_id WHERE UPPER(CONCAT(sys01_company_nm , emp01_kor_nm , f_get_empTrans(emp01_person_id, f_sysdate()::date, 'org_code_nm') , emp01_office_telno , emp01_mobile_telno)) LIKE UPPER(#{searchText}) AND emp03_trans_date = ( SELECT MAX(emp03_trans_date) FROM emp03_trans WHERE emp03_person_id = emp01_person_id AND emp03_trans_date <= f_today() ) AND emp03_trans_cd NOT IN ('800')
AND emp01_company_id = #{companyId}
AND sys01_use_yn = 'true'
AND emp03_trans_cd NOT IN ('900')
) SELECT person_id, company_nm, kor_nm, emp_no, pos_nm, org_nm, office_telno, mobile_telno, email_addr, hire_date, note FROM paging_data WHERE row_num > #{offset} ORDER BY row_num LIMIT #{limit}
